=== GlassItem
using System;

public class GlassItem : Item
{
	protected int curHits;

	protected int maxHits = 10;

	protected float curDamage;

	protected float maxDamage = 100f;

	protected bool useMaxDamage;

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			Health health = parentPlayer.health;
			health.takeDamageActualHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageActualHandlers, new Health.OnTakeDamageHandler(OnTakeDamage));
			Health health2 = parentPlayer.health;
			health2.takeDamageActualHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(health2.takeDamageActualHandlers, new Health.OnTakeDamageHandler(OnTakeDamage));
		}
	}

	public override void Deactivate()
	{
		if (SetParentAsPlayer())
		{
			Health health = parentPlayer.health;
			health.takeDamageActualHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageActualHandlers, new Health.OnTakeDamageHandler(OnTakeDamage));
		}
	}

	public virtual void OnTakeDamage(AttackInfo atkInfo, Entity atkEntity)
	{
		if (useMaxDamage)
		{
			curDamage += atkInfo.damage;
			if (curDamage >= maxDamage)
			{
				Break();
			}
		}
		else
		{
			curHits++;
			if (curHits >= maxHits)
			{
				Break();
			}
		}
	}

	public virtual void Break()
	{
		if (!(parentEntity == null) && parentEntity.inventory != null)
		{
			parentEntity.inventory.RemoveItem(ID, forceOverride: true, showNotice: true);
		}
	}
}
