using System;

public class GoldOnBossCombo : Item
{
	public static string staticID = "GoldOnBossCombo";

	private bool lockDrop;

	private const int goldDropAmount = 50;

	private const int comboThreshold = 33;

	public GoldOnBossCombo()
	{
		ID = staticID;
		category = Category.Misc;
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		Boss.bossComboEventHandlers = (Boss.BossComboEvent)Delegate.Remove(Boss.bossComboEventHandlers, new Boss.BossComboEvent(OnBossCombo));
		MiniBoss.miniBossComboEventHandlers = (MiniBoss.MiniBossComboEvent)Delegate.Remove(MiniBoss.miniBossComboEventHandlers, new MiniBoss.MiniBossComboEvent(OnMiniBossCombo));
		GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Remove(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
		if (givenStatus)
		{
			Boss.bossComboEventHandlers = (Boss.BossComboEvent)Delegate.Combine(Boss.bossComboEventHandlers, new Boss.BossComboEvent(OnBossCombo));
			MiniBoss.miniBossComboEventHandlers = (MiniBoss.MiniBossComboEvent)Delegate.Combine(MiniBoss.miniBossComboEventHandlers, new MiniBoss.MiniBossComboEvent(OnMiniBossCombo));
			GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Combine(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
		}
	}

	private void OnBossCombo(Boss boss, int comboCount)
	{
		OnEnemyCombo(boss, comboCount);
	}

	private void OnMiniBossCombo(MiniBoss miniBoss, int comboCount)
	{
		OnEnemyCombo(miniBoss, comboCount);
	}

	private void OnEnemyCombo(Enemy enemy, int comboCount)
	{
		if (!lockDrop && comboCount >= 33 && !(parentEntity == null) && Globals.InGameScene(string.Empty))
		{
			LootManager.DropGold(parentEntity.transform.position, 50);
			lockDrop = true;
