	{
		currentCount = 0;
		ApplyHealthMod(givenStatus);
	}

	public override void HandleKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
		if (!(healthMod.modValue >= healthMax))
		{
			currentCount++;
			ApplyHealthMod(givenStatus: true);
		}
	}

	private void ApplyHealthMod(bool givenStatus)
	{
		if (givenStatus)
		{
			healthMod.modValue = Mathf.Min(healthMax, healthMin + (float)currentCount * healthInc);
		}
		if (parentEntity != null)
		{
			parentEntity.health.healthStat.Modify(healthMod, givenStatus);
		}
	}
