		{
			if (!(player == null))
			{
				Health health = player.health;
				health.takeDamageActualHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageActualHandlers, new Health.OnTakeDamageHandler(OnTakeDamage));
				if (givenStatus)
				{
					Health health2 = player.health;
					health2.takeDamageActualHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(health2.takeDamageActualHandlers, new Health.OnTakeDamageHandler(OnTakeDamage));
				}
			}
		}
		ApplyCostMods(givenStatus);
		ItemStoreItem.spawnEventHandlers = (ItemStoreItem.SpawnEventHandler)Delegate.Remove(ItemStoreItem.spawnEventHandlers, new ItemStoreItem.SpawnEventHandler(OnItemSpawn));
		SkillStoreItem.spawnEventHandlers = (SkillStoreItem.SpawnEventHandler)Delegate.Remove(SkillStoreItem.spawnEventHandlers, new SkillStoreItem.SpawnEventHandler(OnItemSpawn));
		if (givenStatus)
		{
			ItemStoreItem.spawnEventHandlers = (ItemStoreItem.SpawnEventHandler)Delegate.Combine(ItemStoreItem.spawnEventHandlers, new ItemStoreItem.SpawnEventHandler(OnItemSpawn));
			SkillStoreItem.spawnEventHandlers = (SkillStoreItem.SpawnEventHandler)Delegate.Combine(SkillStoreItem.spawnEventHandlers, new SkillStoreItem.SpawnEventHandler(OnItemSpawn));
		}
	}

	private void OnItemSpawn(ItemStoreItem givenItem)
	{
		ApplyDiscountToItem(givenItem, givenStatus: true);
	}

	private void OnItemSpawn(SkillStoreItem givenItem)
	{
		ApplyDiscountToItem(givenItem, givenStatus: true);
	}

	private void ApplyCostMods(bool givenStatus)
	{
		for (int i = 0; i < ItemStoreItem.currentItems.Count; i++)
		{
			ApplyDiscountToItem(ItemStoreItem.currentItems[i], givenStatus);
		}
		for (int j = 0; j < SkillStoreItem.currentSkills.Count; j++)
		{
			ApplyDiscountToItem(SkillStoreItem.currentSkills[j], givenStatus);
		}
	}

	private void ApplyDiscountToItem(StoreItem givenItem, bool givenStatus)
	{
		if (!(givenItem == null) && !givenItem.usePlatinumCost)
		{
			givenItem.costStat.Modify(discountMod, givenStatus);
			givenItem.UpdatePrice();
		}
	}

	private void OnTakeDamage(AttackInfo givenAtkInfo, Entity attackEntity)
	{
		if (cdStopwatch.IsRunning || parentPlayer == null || parentPlayer.health.CurrentHealthValue <= 0 || parentPlayer.fsm.currentStateName.Contains("Dead") || UnityEngine.Random.value > stealChance)
