		if (skillToSteal != null && itemToSteal != null)
		{
			if (Globals.RandBool)
			{
				skillToSteal = null;
			}
			else
			{
				itemToSteal = null;
			}
		}
		cdStopwatch.IsRunning = true;
		if (skillToSteal != null)
		{
			parentPlayer.RemoveSkill(skillToSteal);
		}
		else
		{
			parentPlayer.inventory.RemoveItem(itemToSteal.ID, forceOverride: false, showNotice: true);
		}
